```sql
-- CONFORMS TO 1NF: one atomic value per row
CREATE TABLE orders (
    order_id  BIGINT PRIMARY KEY,
    customer  VARCHAR(100)
);
CREATE TABLE order_tags (
    order_id  BIGINT REFERENCES orders(order_id),
    tag       VARCHAR(50),            -- one tag per row
    PRIMARY KEY (order_id, tag)
);
-- Now this uses an index: SELECT order_id FROM order_tags WHERE tag = 'sale';
```

```sql
CREATE TABLE departments (
    department_id       BIGINT PRIMARY KEY,
    department_name     VARCHAR(100) NOT NULL,
    department_location VARCHAR(100)
);

CREATE TABLE employees (
    employee_id   BIGINT PRIMARY KEY,
    employee_name VARCHAR(100),
    department_id BIGINT REFERENCES departments(department_id)
);
```

Department facts now depend on the Department key; Employee keeps only the relationship.

```sql
CREATE TABLE categories (
    category_id   BIGINT PRIMARY KEY,
    category_name VARCHAR(100) NOT NULL
);

CREATE TABLE products (
    product_id   BIGINT PRIMARY KEY,
    product_name VARCHAR(100) NOT NULL,
    category_id  BIGINT REFERENCES categories(category_id)
);

CREATE TABLE orders (
    order_id BIGINT PRIMARY KEY
);

CREATE TABLE order_items (
    order_id   BIGINT REFERENCES orders(order_id),
    product_id BIGINT REFERENCES products(product_id),
    quantity   INT NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (order_id, product_id)
);

CREATE TABLE product_tags (
    product_id BIGINT REFERENCES products(product_id),
    tag        VARCHAR(50),
    PRIMARY KEY (product_id, tag)
);
```

Joining order_items to products and categories reconstructs the original product facts; joining product_tags gives one row per tag instead of parsing a CSV value.

```sql
-- BCNF FIX: split so every determinant is a key
CREATE TABLE teaches (
    teacher  VARCHAR(50) PRIMARY KEY,
    subject  VARCHAR(50)
);
CREATE TABLE takes (
    student  VARCHAR(50),
    teacher  VARCHAR(50) REFERENCES teaches(teacher),
    PRIMARY KEY (student, teacher)
);
```
